// Vocal Studio, tested with synthetic singing fed to Chromium as a fake microphone.
// The WAV files are generated by tests/fixtures/make-voice.py (run automatically if missing).
const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('path');
const fs = require('fs');
const { execFileSync } = require('child_process');
const { chromium } = require('playwright');
const serve = require('./serve');
const FIX = path.join(__dirname, '..', 'fixtures');
if (!fs.existsSync(path.join(FIX, 'voice-five.wav'))) execFileSync('python3', [path.join(FIX, 'make-voice.py'), FIX]);

async function withMic(file, port, fn) {
  const srv = serve(path.join(__dirname, '..', '..', 'app'), port);
  const b = await chromium.launch({ args: ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream', '--use-file-for-fake-audio-capture=' + path.join(FIX, file), '--autoplay-policy=no-user-gesture-required'] });
  try {
    const p = await (await b.newContext({ permissions: ['microphone'] })).newPage();
    const errors = []; p.on('pageerror', e => errors.push(e.message));
    await p.goto('http://localhost:' + port + '/');
    await p.evaluate(() => { const g = window.__gpa; g.S().profile.onboarded = true; g.S().voice = { range: { lo: 48, hi: 64, at: '2026-11-07' } }; });
    const r = await fn(p);
    return { r, errors };
  } finally { await b.close(); srv.close(); }
}
const runFive = p => p.evaluate(() => new Promise(res => {
  const host = document.createElement('div'); document.body.appendChild(host);
  const run = runVoiceEx(host, vexById('five'), { skipIntro: true, rounds: 1, onDone: sum => { res({ sum, text: host.textContent }); run.stop(); } });
  setTimeout(() => res({ timeout: true, text: host.textContent }), 50000);
}));

test('Vocal Studio: a five-note scale sung in tune scores high', async () => {
  const { r, errors } = await withMic('voice-five.wav', 8801, runFive);
  assert.ok(!r.timeout, 'finished: ' + r.text.slice(0, 200));
  assert.ok(r.sum.score >= 85, 'score ' + r.sum.score);
  assert.ok(r.sum.inTune >= 85, 'in tune ' + r.sum.inTune);
  assert.ok(Math.abs(r.sum.cents) <= 10, 'no tendency: ' + r.sum.cents);
  assert.deepEqual(errors, []);
});

test('Vocal Studio: the same scale sung 40 cents flat scores lower and is called flat', async () => {
  const { r, errors } = await withMic('voice-five-flat.wav', 8802, runFive);
  assert.ok(!r.timeout, 'finished: ' + r.text.slice(0, 200));
  assert.ok(r.sum.score <= 50, 'score ' + r.sum.score);
  assert.ok(r.sum.cents <= -30 && r.sum.cents >= -50, 'measured about 40 cents flat: ' + r.sum.cents);
  assert.match(r.text, /tend to sing flat/);
  assert.deepEqual(errors, []);
});

test('Vocal Studio: the screens, the tuner, the range finder and a saved session', async () => {
  const { r, errors } = await withMic('voice-a3.wav', 8803, async p => {
    const out = {};
    out.nav = await p.evaluate(() => !!document.querySelector('[data-to="voice"], [data-nav="voice"], a[href*="voice"]') || NAV.some(n => n[0] === 'voice'));
    for (const tab of ['today', 'exercises', 'learn', 'progress']) { await p.evaluate(t => window.__gpa.go('voice', { tab: t }), tab); await p.waitForTimeout(150); out[tab] = await p.evaluate(() => document.querySelector('#main').textContent.length); }
    await p.evaluate(() => window.__gpa.go('voice', { tab: 'tuner' }));
    await p.waitForFunction(() => /A3/.test(document.querySelector('#tnote') ? document.querySelector('#tnote').textContent : ''), null, { timeout: 15000 });
    out.tuner = await p.textContent('#tnote');
    await p.evaluate(() => window.__gpa.go('voice', { tab: 'today', range: 1 }));
    await p.waitForFunction(() => document.querySelector('#rflo') && document.querySelector('#rflo').textContent === 'A3', null, { timeout: 15000 });
    await p.click('#rfnext'); await p.waitForFunction(() => !document.querySelector('#rfnext').disabled, null, { timeout: 15000 });
    await p.click('#rfnext');
    out.small = await p.textContent('#rfinstr');
    out.saved = await p.evaluate(() => { voxSave({ ex: 'match', score: 77, inTune: 70, cents: -8, n: 6, seconds: null }); const v = window.__gpa.S().voice; const clean = window.Sanitize.cleanState(JSON.parse(JSON.stringify(window.__gpa.S())), {}); return { best: v.best.match, sessions: v.sessions.length, clean: clean.voice.best.match, range: clean.voice.range }; });
    out.key = await p.evaluate(() => { const P = { title: 'Test song', key: 'C', melodies: { Chorus: { notes: [{ m: 72 }, { m: 76 }, { m: 79 }, { m: 77 }] } } }; window.__gpa.S().songs = [P]; return bestKeyFor(P); });
    await p.evaluate(() => window.__gpa.go('voice', { tab: 'progress' })); await p.waitForTimeout(150);
    out.progressText = await p.textContent('#main');
    return out;
  });
  assert.equal(r.nav, true);
  ['today', 'exercises', 'learn', 'progress'].forEach(t => assert.ok(r[t] > 200, t + ' renders'));
  assert.equal(r.tuner, 'A3');
  assert.match(r.small, /range is very small/);
  assert.deepEqual(r.saved, { best: 77, sessions: 1, clean: 77, range: { lo: 48, hi: 64, at: '2026-11-07' } });
  assert.match(r.progressText, /C3 to E4/); assert.match(r.progressText, /best key for your voice/i);
  assert.equal(r.key.fits, true); assert.ok(r.key.lo >= 49 && r.key.hi <= 63, JSON.stringify(r.key));
  assert.deepEqual(errors, []);
});

test('Vocal Studio: every exercise starts, fits the singer\'s range, and finishes with a summary', async () => {
  const { r, errors } = await withMic('voice-a3.wav', 8804, p => p.evaluate(async () => {
    const out = {}, wait = ms => new Promise(res => setTimeout(res, ms));
    for (const def of VEX) {
      const host = document.createElement('div'); document.body.appendChild(host);
      let done = null;
      const run = runVoiceEx(host, def, { rounds: 2, count: 2, onDone: s => { done = s; } });
      out[def.id + 'Intro'] = /How this exercise works/.test(host.textContent); host.querySelector('.vx-intro button').click();
      await wait(1200);
      const notes = [...host.querySelectorAll('.vx-t b')].map(b => b.textContent);
      for (let k = 0; k < 40 && !done; k++) { const b = host.querySelector('#vxskip'); if (b) b.click(); await wait(450); }
      out[def.id] = { done: !!done, n: done ? done.n : 0, notes, summary: !!host.querySelector('.vx-sum') };
      run.stop(); host.remove();
    }
    // range fitting: all targets inside the singer's range (C3 to E4, MIDI 48 to 64), allowing harmony below
    const flat = [].concat(...vexRounds(vexById('five'), { rounds: 9 }), ...vexMatch(20), ...vexEcho(10), ...vexIntervals(14).map(x => [x.root, x.target]));
    out.outside = flat.filter(m => m < 48 || m > 66);
    out.harmonyFit = vexHarmony(4).map(h => ({ lo: Math.min(...h.harmony), hi: Math.max(...h.melody) }));
    return out;
  }));
  VEXIDS.forEach(id => { assert.equal(r[id + 'Intro'], true, id + ' shows its directions first'); assert.ok(r[id].done && r[id].summary, id + ' finishes with a summary: ' + JSON.stringify(r[id])); assert.ok(r[id].notes.length > 0, id + ' shows its target notes'); });
  assert.deepEqual(r.outside, []);
  r.harmonyFit.forEach(h => { assert.ok(h.lo >= 48 && h.hi <= 66, 'harmony fits: ' + JSON.stringify(h)); });
  assert.deepEqual(errors, []);
});
const VEXIDS = ['match', 'five', 'arp', 'scale', 'minor', 'interval', 'sustain', 'echo', 'runs', 'harmony'];
